import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;
  const group = new Group();

  // Geometry and material
  const geometry = new PlaneGeometry(1, 1);
  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    transparent: true,
    depthWrite: false,
  });
  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  // Load texture
  const imageUrl = config.imageUrl || config.meshUrl || '';
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
      // Adjust mesh scale to preserve image aspect ratio
      const img = tex.image;
      if (img && img.width && img.height) {
        const aspect = img.width / img.height;
        mesh.scale.set(aspect, 1, 1);
      }
    });
  }

  // Interaction handlers
  const hoverTimeline = gsap.timeline({ paused: true });
  hoverTimeline.to(mesh.position, {
    y: '+=0.15',
    duration: 0.7,
    ease: 'power3.out',
  });

  const clickTimeline = gsap.timeline({ paused: true });
  clickTimeline
    .to(
      mesh.scale,
      {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out(1)',
      },
      0
    )
    .to(
      mesh.scale,
      {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.12,
        ease: 'back.out(1)',
      },
      '+=0.05'
    );

  group.userData.handlers = {
    hover: {
      enter: () => hoverTimeline.play(),
      leave: () => hoverTimeline.reverse(),
    },
    click: () => {
      clickTimeline.restart();
      ctx.emit('hub-journal.select', {});
    },
  };

  // Cleanup
  group.userData.cleanup = () => {
    hoverTimeline.kill();
    clickTimeline.kill();
    if (material.map) material.map.dispose();
    material.dispose();
    geometry.dispose();
  };

  return group;
}
